import { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';

interface ForteHeaderProps {
  isScrolled: boolean;
}

export default function ForteHeader({ isScrolled }: ForteHeaderProps) {
  const [isSitemapOpen, setIsSitemapOpen] = useState(false);
  const [isMobileNavOpen, setIsMobileNavOpen] = useState(false);

  useEffect(() => {
    const handleEsc = (e: KeyboardEvent) => {
      if (e.key === 'Escape' && isSitemapOpen) {
        setIsSitemapOpen(false);
      }
    };
    document.addEventListener('keydown', handleEsc);
    return () => document.removeEventListener('keydown', handleEsc);
  }, [isSitemapOpen]);

  useEffect(() => {
    if (isSitemapOpen || isMobileNavOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = '';
    }
    return () => {
      document.body.style.overflow = '';
    };
  }, [isSitemapOpen, isMobileNavOpen]);

  const navItems = [
    {
      title: '미호의원',
      link: '#philosophy',
      children: [
        { title: '미호의원 소개', link: '#philosophy' },
        { title: '진료 철학', link: '#philosophy' },
        { title: '비급여 진료비 안내', link: '/non-benefit' },
      ],
    },
    {
      title: '진료 안내',
      link: '#treatments',
      children: [
        { title: '리프팅·수분·탄력', link: '#treatments' },
        { title: '필러·보톡스', link: '#treatments' },
        { title: '점·기미·주근깨', link: '#treatments' },
        { title: '여드름·홍조', link: '#treatments' },
        { title: '피부질환', link: '#treatments' },
        { title: '제모', link: '#treatments' },
        { title: '수액클리닉', link: '#treatments' },
        { title: '기능의학센터', link: '#treatments' },
      ],
    },
    {
      title: '예약·상담',
      link: '#consultation',
      children: [
        { title: '전화 예약', link: 'tel:055-363-2575' },
        { title: '온라인 예약', link: 'https://booking.naver.com/booking/13/bizes/1093628' },
        { title: '카카오톡 상담', link: 'http://pf.kakao.com/_Jxdixoxj' },
        { title: '진료시간 안내', link: '#consultation' },
      ],
    },
    {
      title: '오시는 길',
      link: '#location',
      children: [
        { title: '위치 안내', link: '#location' },
        { title: '네이버 지도', link: 'https://naver.me/FOk2dKnO' },
      ],
    },
  ];

  return (
    <>
      <header className={`forte-header ${isScrolled ? 'scrolled' : ''}`}>
        <div className="forte-header-container">
          <Link to="/" className="forte-logo" title="메인으로">
            <img
              className="logo-white"
              src="/miho/logo_w.svg"
              alt="미호의원"
            />
            <img
              className="logo-color"
              src="/miho/logo.svg"
              alt="미호의원"
            />
          </Link>

          <div className="forte-header-right">
            <div className="forte-header-inner">
              <nav className="forte-nav">
                <ul className="forte-nav-list">
                  {navItems.map((item, idx) => (
                    <li key={idx} className="forte-nav-item">
                      <a href={item.link} className="forte-nav-link">
                        {item.title}
                      </a>
                      <ul className="forte-nav-submenu">
                        {item.children.map((child, childIdx) => (
                          <li key={childIdx}>
                            {child.link.startsWith('/') ? (
                              <Link to={child.link} className="forte-nav-sublink">
                                {child.title}
                              </Link>
                            ) : (
                              <a
                                href={child.link}
                                className="forte-nav-sublink"
                                target={child.link.startsWith('http') ? '_blank' : undefined}
                                rel={child.link.startsWith('http') ? 'noopener noreferrer' : undefined}
                              >
                                {child.title}
                              </a>
                            )}
                          </li>
                        ))}
                      </ul>
                    </li>
                  ))}
                </ul>
              </nav>

              <div className="forte-util-wrap">
                <a href="tel:055-363-2575" className="forte-tel-btn">
                  <i className="ri-phone-line"></i>
                  <span className="forte-tel-text">055-363-2575</span>
                </a>
                <button
                  type="button"
                  className="forte-sitemap-btn"
                  onClick={() => setIsSitemapOpen(true)}
                  aria-label="전체메뉴"
                >
                  <span></span>
                  <span></span>
                  <span></span>
                </button>
              </div>
            </div>
            <div className="forte-header-depth2"></div>
          </div>

          <button
            className="forte-mobile-btn"
            type="button"
            onClick={() => setIsMobileNavOpen(true)}
            aria-label="모바일 메뉴"
          >
            <span></span>
            <span></span>
          </button>
        </div>
      </header>

      {/* Mobile Navigation */}
      <div
        className={`forte-mobile-bg ${isMobileNavOpen ? 'active' : ''}`}
        onClick={() => setIsMobileNavOpen(false)}
      ></div>

      <aside className={`forte-mobile-nav ${isMobileNavOpen ? 'active' : ''}`}>
        <div className="forte-mobile-head">
          <Link to="/" className="forte-mobile-logo">
            <img src="/miho/logo.svg" alt="미호의원" />
          </Link>
          <button
            className="forte-mobile-close"
            onClick={() => setIsMobileNavOpen(false)}
            aria-label="닫기"
          >
            <i className="ri-close-line"></i>
          </button>
        </div>

        <div className="forte-mobile-body">
          <ul className="forte-mobile-list">
            {navItems.map((item, idx) => (
              <li key={idx} className="forte-mobile-item">
                <a href={item.link} className="forte-mobile-title">
                  {item.title}
                </a>
                <ul className="forte-mobile-sublist">
                  {item.children.map((child, childIdx) => (
                    <li key={childIdx}>
                      {child.link.startsWith('/') ? (
                        <Link to={child.link} className="forte-mobile-sublink">
                          {child.title}
                        </Link>
                      ) : (
                        <a
                          href={child.link}
                          className="forte-mobile-sublink"
                          target={child.link.startsWith('http') ? '_blank' : undefined}
                          rel={child.link.startsWith('http') ? 'noopener noreferrer' : undefined}
                        >
                          {child.title}
                        </a>
                      )}
                    </li>
                  ))}
                </ul>
              </li>
            ))}
          </ul>

          <div className="forte-mobile-footer">
            <a href="tel:055-363-2575" className="forte-mobile-tel">
              <i className="ri-phone-line"></i>
              055-363-2575
            </a>
            <div className="forte-mobile-sns">
              <a href="https://www.instagram.com/miho_clinic" target="_blank" rel="noopener noreferrer">
                <i className="ri-instagram-line"></i>
              </a>
              <a href="https://blog.naver.com/miho3632575" target="_blank" rel="noopener noreferrer">
                <i className="ri-blogger-line"></i>
              </a>
              <a href="http://pf.kakao.com/_Jxdixoxj" target="_blank" rel="noopener noreferrer">
                <i className="ri-chat-3-line"></i>
              </a>
            </div>
          </div>
        </div>
      </aside>

      {/* Sitemap */}
      <div className={`forte-sitemap ${isSitemapOpen ? 'active' : ''}`}>
        <div className="forte-sitemap-container">
          <div className="forte-sitemap-header">
            <Link to="/" className="forte-sitemap-logo">
              <img src="/miho/logo.svg" alt="미호의원" />
            </Link>
            <button
              type="button"
              className="forte-sitemap-close"
              onClick={() => setIsSitemapOpen(false)}
            >
              <i className="ri-close-line"></i>
              <span>Close</span>
            </button>
          </div>

          <div className="forte-sitemap-body">
            <nav className="forte-sitemap-nav">
              <ul className="forte-sitemap-list">
                {navItems.map((item, idx) => (
                  <li key={idx} className="forte-sitemap-item">
                    <a href={item.link} className="forte-sitemap-title">
                      <span className="forte-sitemap-num">
                        {String(idx + 1).padStart(2, '0')}
                      </span>
                      {item.title}
                    </a>
                    <ul className="forte-sitemap-sublist">
                      {item.children.map((child, childIdx) => (
                        <li key={childIdx}>
                          {child.link.startsWith('/') ? (
                            <Link to={child.link} className="forte-sitemap-sublink">
                              {child.title}
                            </Link>
                          ) : (
                            <a
                              href={child.link}
                              className="forte-sitemap-sublink"
                              target={child.link.startsWith('http') ? '_blank' : undefined}
                              rel={child.link.startsWith('http') ? 'noopener noreferrer' : undefined}
                            >
                              {child.title}
                            </a>
                          )}
                        </li>
                      ))}
                    </ul>
                  </li>
                ))}
              </ul>
            </nav>
          </div>
        </div>
      </div>
    </>
  );
}
